import{_ as a,o as l,c as n,aw as e}from"./chunks/framework.DLufY-ao.js";const d=JSON.parse('{"title":"История версий","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/react/main/version.md","filePath":"wiki/dev-commit/framework-react/react/main/version.md"}'),o={name:"wiki/dev-commit/framework-react/react/main/version.md"};function t(p,s,c,i,r,y){return l(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="история-версии" tabindex="-1">История версий <a class="header-anchor" href="#история-версии" aria-label="Permalink to &quot;История версий&quot;">​</a></h1><h2 id="react-19-2024" tabindex="-1">React 19 (2024) <a class="header-anchor" href="#react-19-2024" aria-label="Permalink to &quot;React 19 (2024)&quot;">​</a></h2><details class="details custom-block"><summary>Серверные компоненты</summary><ul><li>Директива &quot;use server&quot;</li><li>Код в этом блоке будет запускаться только на сервере</li></ul></details><details class="details custom-block"><summary>Фиксы гидрации</summary><ul><li>Проблема гидрации: стейт на сервере должен совпадть со стетом на клиенте, чтобы не делать повторно одни и те же запросы</li><li>Будет меньше сложностей с гидрацией</li></ul></details><details class="details custom-block"><summary>Мета-теги в JSX</summary><ul><li>Мета-теги можно указывать в JSX. React будет ставить их в <code>&lt;head&gt;</code></li></ul></details><details class="details custom-block"><summary>Подгрузка css-файлов из JSX</summary><ul><li>Можно добавлать тег <code>&lt;link&gt;</code> с указанием ссылки на CSS-файл и дополнительно указывать приоритетность стилей</li></ul></details><details class="details custom-block"><summary>Suspense при подгрузке стилей</summary><ul><li>Можно добавить компонент загрузки при подгрузке стилей</li></ul></details><details class="details custom-block"><summary>Методы для быстрой загрузки файлов</summary><ul><li>Дополнительные методы: <code>preinit</code>, <code>preload</code>, <code>prefetchDNS</code>, <code>preconnect</code>, <code>preinitModule</code>, <code>preloadModule</code></li><li>Методы позволяют ускорить загрузку файлов с сервера</li></ul></details><details class="details custom-block"><summary>Работа с формами в React</summary><ul><li>Добавился атрибут <code>action</code> у тега <code>&lt;form&gt;</code>. Можно указать асинхронную функцию, куда придут данные из формы</li></ul></details><details class="details custom-block"><summary>Новые методы форм</summary><ul><li><code>useOptimistic</code></li><li><code>useFormStatus</code></li><li><code>useActionState</code></li></ul></details><details class="details custom-block"><summary>Ref как свойство</summary><ul><li>Можно пробрасывать как props в другие компоненты</li></ul></details><details class="details custom-block"><summary>Хук useMemo больше не нужен</summary><ul><li>React будет использовать по-умолчанию</li></ul></details><details class="details custom-block"><summary>Функция use</summary><ul><li>Похожа на хук, но можно использовать в условных операторах и т.д.</li></ul></details><hr><h2 id="react-18-2022-март" tabindex="-1">React 18 (2022, Март) <a class="header-anchor" href="#react-18-2022-март" aria-label="Permalink to &quot;React 18 (2022, Март)&quot;">​</a></h2><details class="details custom-block"><summary>Automatic batching</summary><ul><li><strong>Batching в React</strong> (батчинг) - процесс группировки нескольких вызовов обновления состояний в один этап ререндера. Другими словами, пакетная обработка</li><li>Добавилась возможность автоматического батчинга обновления состояний для асинхронных операций: promise, timeouts, fetch-запросы, что положительно сказывается на производительности</li><li>Раньше группировка происходила только внутри обработчиков событий</li></ul><p><strong>Пример</strong></p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#4078F2;"> App</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> () </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> {</span></span>
<span class="line"><span style="color:#A626A4;">  const</span><span style="color:#383A42;"> [</span><span style="color:#986801;">count</span><span style="color:#383A42;">, </span><span style="color:#986801;">setCount</span><span style="color:#383A42;">] </span><span style="color:#0184BC;">=</span><span style="color:#4078F2;"> useState</span><span style="color:#383A42;">(</span><span style="color:#986801;">0</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#A626A4;">  const</span><span style="color:#383A42;"> [</span><span style="color:#986801;">flag</span><span style="color:#383A42;">, </span><span style="color:#986801;">setFlag</span><span style="color:#383A42;">] </span><span style="color:#0184BC;">=</span><span style="color:#4078F2;"> useState</span><span style="color:#383A42;">(</span><span style="color:#986801;">false</span><span style="color:#383A42;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">  const</span><span style="color:#4078F2;"> handleClick</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> () </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> {</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">    // До React 18 следующие вызовы не батчились</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">    // Установка состояния происходит «после» события в колбэке асинхронного вызова</span></span>
<span class="line"><span style="color:#4078F2;">    fetchSomething</span><span style="color:#383A42;">().</span><span style="color:#4078F2;">then</span><span style="color:#383A42;">(() </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> {</span></span>
<span class="line"><span style="color:#4078F2;">      setCount</span><span style="color:#383A42;">((c) </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> c </span><span style="color:#0184BC;">+</span><span style="color:#986801;"> 1</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// Спровоцирует ререндер</span></span>
<span class="line"><span style="color:#4078F2;">      setFlag</span><span style="color:#383A42;">((f) </span><span style="color:#A626A4;">=&gt;</span><span style="color:#0184BC;"> !</span><span style="color:#383A42;">f); </span><span style="color:#A0A1A7;font-style:italic;">// Спровоцирует ререндер</span></span>
<span class="line"><span style="color:#383A42;">    });</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">    // В React 18</span></span>
<span class="line"><span style="color:#4078F2;">    fetchSomething</span><span style="color:#383A42;">().</span><span style="color:#4078F2;">then</span><span style="color:#383A42;">(() </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> {</span></span>
<span class="line"><span style="color:#4078F2;">      setCount</span><span style="color:#383A42;">((c) </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> c </span><span style="color:#0184BC;">+</span><span style="color:#986801;"> 1</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// Не вызывает ререндер</span></span>
<span class="line"><span style="color:#4078F2;">      setFlag</span><span style="color:#383A42;">((f) </span><span style="color:#A626A4;">=&gt;</span><span style="color:#0184BC;"> !</span><span style="color:#383A42;">f); </span><span style="color:#A0A1A7;font-style:italic;">// Не вызывает ререндер</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">      // React будет вызывать ререндер только один раз, в конце</span></span>
<span class="line"><span style="color:#383A42;">    });</span></span>
<span class="line"><span style="color:#383A42;">  };</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">  return</span><span style="color:#383A42;"> (</span></span>
<span class="line"><span style="color:#383A42;">    &lt;</span><span style="color:#E45649;">div</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">      &lt;</span><span style="color:#E45649;">button</span><span style="color:#986801;"> onClick</span><span style="color:#383A42;">={handleClick}&gt;Next&lt;/</span><span style="color:#E45649;">button</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">      &lt;</span><span style="color:#E45649;">h1</span><span style="color:#986801;"> style</span><span style="color:#383A42;">={{ </span><span style="color:#E45649;">color</span><span style="color:#0184BC;">:</span><span style="color:#383A42;"> flag ? </span><span style="color:#50A14F;">&quot;blue&quot;</span><span style="color:#383A42;"> : </span><span style="color:#50A14F;">&quot;black&quot;</span><span style="color:#383A42;"> }}&gt;{count}&lt;/</span><span style="color:#E45649;">h1</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">    &lt;/</span><span style="color:#E45649;">div</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  );</span></span>
<span class="line"><span style="color:#383A42;">};</span></span></code></pre></div></details><details class="details custom-block"><summary>Concurrent rendering</summary><ul><li><strong>Concurrent rendering</strong> (конкурентный режим) предназначен для более плавной работы приложения на устройстве пользователя. Одна из областей применения — прерываемый рендеринг. Представьте, что пользователь вводит в строку поиска текст. Событие обновляет состояние компонента, и происходит рендер нового списка результатов. Во время этого процесса залипает ввод: браузер не может обновить введенный в поле текст, т.к. занимается рендером нового списка результатов. Конкурентный режим исправляет это ограничение и делает рендер прерываемым</li></ul></details><details class="details custom-block"><summary>Новые хуки</summary><ul><li><code>useTransition</code></li><li><code>useDeferredValue</code></li><li><code>useId</code></li><li><code>useSyncExternalStore</code></li><li><code>useInsertionEffect</code></li></ul></details><details class="details custom-block"><summary>Concurrent Suspense</summary><ul><li>Существенное изменение для пользователей заключается в рендере дочерних элементов внутри Suspense</li><li>В React 17 компонент &lt;Sibling /&gt; будет смонтирован и вызваны его эффекты. Затем он будет скрыт</li><li>В React 18 компонент &lt;Sibling /&gt; смонтируется только после того, как &lt;SuspendedComponent /&gt; загрузится</li></ul><p><strong>Пример</strong></p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#4078F2;"> App</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> () </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> {</span></span>
<span class="line"><span style="color:#A626A4;">  return</span><span style="color:#383A42;"> (</span></span>
<span class="line"><span style="color:#383A42;">    &lt;</span><span style="color:#C18401;">Suspense</span><span style="color:#986801;"> fallback</span><span style="color:#383A42;">={&lt;</span><span style="color:#C18401;">Loading</span><span style="color:#383A42;"> /&gt;}&gt;</span></span>
<span class="line"><span style="color:#383A42;">      &lt;</span><span style="color:#C18401;">SuspendedComponent</span><span style="color:#383A42;"> /&gt;</span></span>
<span class="line"><span style="color:#383A42;">      &lt;</span><span style="color:#C18401;">Sibling</span><span style="color:#383A42;"> /&gt;</span></span>
<span class="line"><span style="color:#383A42;">    &lt;/</span><span style="color:#C18401;">Suspense</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  );</span></span>
<span class="line"><span style="color:#383A42;">};</span></span></code></pre></div></details><details class="details custom-block"><summary>Потоковый SSR</summary><ul><li>Выборочная гидратация</li><li>Метод hydrate() используется в SSR и позволяет повесить обработчики событий на узлы DOM-дерева, которые были отрендерены на стороне сервера. Это позволяет улучшить опыт клиента при первой загрузки страницы</li><li>React не будет блокировать UI во время гидратации — этот процесс будет происходить во время простоя браузера. Поэтому пользовательские события будут обрабатываться сразу</li><li>Потоковая отправка HTML</li><li>Позволяет отправить HTML клиенту без загрузки всех данных для рендера на сервер. Как только данные будут получены, они отрендерятся на сервере и отправятся на клиент. Например, есть блок с комментариями, и мы можем асинхронно загружать по ним информацию, отдавая HTML. Когда комментарии будут получены, отрендерить их и отправить клиенту в конце HTML-документа</li></ul></details><h2 id="react-17-2020-октябрь" tabindex="-1">React 17 (2020, Октябрь) <a class="header-anchor" href="#react-17-2020-октябрь" aria-label="Permalink to &quot;React 17 (2020, Октябрь)&quot;">​</a></h2><details class="details custom-block"><summary>Изменение в делегировании событий</summary><ul><li>React использует делегирование событий и привязывал все события к объекту <code>document</code>. Теперь все обработчики крепятся к корневому элементу <code>root</code>, а не объекту <code>document</code></li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> rootNode</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> document.</span><span style="color:#4078F2;">getElementById</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;root&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">ReactDOM.</span><span style="color:#4078F2;">render</span><span style="color:#383A42;">(&lt;</span><span style="color:#C18401;">App</span><span style="color:#383A42;"> /&gt;, rootNode);</span></span></code></pre></div></details><details class="details custom-block"><summary>SyntheticEvent Even Pooling</summary><ul><li>Убрана оптимизация событий, которая более не актуальна в современных браузерах</li></ul><p><strong>Такой код не будет валиться с ошибкой</strong></p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">function</span><span style="color:#4078F2;"> handleChange</span><span style="color:#383A42;">(event) {</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">  // это работает в 16 React только если добавить event.persist()</span></span>
<span class="line"><span style="color:#4078F2;">  setData</span><span style="color:#383A42;">((data) </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> ({</span></span>
<span class="line"><span style="color:#0184BC;">    ...</span><span style="color:#383A42;">data,</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">    // This crashes in React 16 and earlier:</span></span>
<span class="line"><span style="color:#E45649;">    text</span><span style="color:#0184BC;">:</span><span style="color:#383A42;"> event.</span><span style="color:#E45649;">target</span><span style="color:#383A42;">.</span><span style="color:#E45649;">value</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#383A42;">  }));</span></span>
<span class="line"><span style="color:#383A42;">}</span></span></code></pre></div></details><details class="details custom-block"><summary>Браузерные события</summary><ul><li>Событие <code>onScroll</code> больше не всплывает, чтобы избежать текущей путаницы</li><li>События <code>onFocus</code> и onBlur изменены &quot;под капотом&quot; на нативные focusin и focusout</li><li><code>onClickCapture</code> и другие Capture-события теперь используют браузерные обработчики событий</li></ul></details><details class="details custom-block"><summary>useEffect() теперь полностью асинхронный</summary><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">useEffect</span><span style="color:#383A42;">(() </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> {</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">  // This is the effect itself</span></span>
<span class="line"><span style="color:#A626A4;">  return</span><span style="color:#383A42;"> () </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> {</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">    // This is its cleanup</span></span>
<span class="line"><span style="color:#383A42;">  };</span></span>
<span class="line"><span style="color:#383A42;">});</span></span></code></pre></div><ul><li>Если раньше только функция эффекта запускалась асинхронно, тогда как возвращаемая функция для очистки подписок запускалась синхронно, так же как и метод componentWillUnmount(), то теперь и эта функция работает асинхронно, что улучшает производительность в случае перерисовки большого количества элементов, например, когда на сайте присутствуют вкладки, или при переходе со страницы на страницу</li><li>Для синхронной работы, можно по-прежнему использовать useLayoutEffect(), который остался незатронутым</li></ul></details><details class="details custom-block"><summary>Улучшенный стек вызовов при ошибках</summary><ul><li>Когда выбрасывается ошибка, браузер показывает stack trace с названиями функций и их местоположения. К сожалению, довольно трудно по этому стеку вызовов понять, в каком месте и в каком компоненте была вызвана ошибка на самом деле</li><li>В React 17 используется новых механизм по генерации стека вызовов, что позволяет увидеть дерево React-компонентов, которое привело к ошибке, даже в production-среде</li></ul></details><h2 id="react-16-2017-сентябрь" tabindex="-1">React 16 (2017, Сентябрь) <a class="header-anchor" href="#react-16-2017-сентябрь" aria-label="Permalink to &quot;React 16 (2017, Сентябрь)&quot;">​</a></h2><details class="details custom-block"><summary>Фрагменты</summary><ul><li>Фрагменты позволяют формировать список дочерних элементов, не создавая лишних узлов в DOM</li></ul></details><details class="details custom-block"><summary>Обработка ошибок</summary><ul><li>Обработка ошибок (error boundaries) - специальные компоненты, которые перехватывают ошибки в своём поддереве и позволяют вывести резервный UI</li></ul></details><details class="details custom-block"><summary>Порталы</summary><ul><li>Порталы - рендера дочерних компонентов в DOM-узел, который находится за пределами дерева родительского компонента</li></ul></details><details class="details custom-block"><summary>Поддержка произвольных DOM-атрибутов</summary><ul><li>Вместо игнорирования неизвестных HTML и SVG атрибутов, теперь React будет просто передавать их в DOM</li></ul></details><details class="details custom-block"><summary>Улучшения в серверном рендере</summary><ul><li>Поддерживает стриминг, так что вы можете быстрее начинать отправлять байты клиенту. И благодаря новой стратегии сборки, которая убирает из кода обращения к process.env (хотите верьте, хотите — нет, но чтение process.env в Node очень медленное!), вам больше не надо бандлить React для получения хорошей производительности серверного рендеринга</li></ul></details><details class="details custom-block"><summary>Уменьшенный размер файла</summary></details><details class="details custom-block"><summary>Зависимость от коллекций Map и Set</summary></details>`,34)])])}const m=a(o,[["render",t]]);export{d as __pageData,m as default};
